import math

def compute(inputs):
    data = inputs['data']
    interval_width = inputs['interval_width']
    target_interval_start = inputs['target_interval_start']
    target_interval_end = inputs['target_interval_end']
    if not data:
        return 0
    if interval_width <= 0:
        raise ValueError('Interval width must be a positive number.')
    min_value, max_value = (min(data), max(data))
    intervals = []
    current_start = min_value
    while current_start <= max_value:
        current_end = current_start + interval_width
        intervals.append((current_start, current_end))
        current_start = current_end
    if not intervals and data:
        intervals.append((min_value, min_value + interval_width))
    frequency_distribution = {interval: 0 for interval in intervals}
    for value in data:
        for start, end in intervals:
            if start <= value < end:
                frequency_distribution[start, end] += 1
                break
    target_frequency = 0
    target_key = (target_interval_start, target_interval_end)
    if target_key in frequency_distribution:
        target_frequency = frequency_distribution[target_key]
    return target_frequency

